"""Authored conversations. No generated dialogue or inferred relationship scores."""
def scene(title, opening, *choices):
    return {'title': title, 'opening': opening, 'choices': {k:{'label':label,'response':reply} for k,(label,reply) in zip(('curious','warm','candid'),choices)}}

